### 5.5 Add Workflow History Query

**File:** `backend/src/FactoryApp.GraphQL/Queries/WorkflowQuery.cs` (NEW)

Expose workflow history to frontend for debugging:

```csharp
[Query]
public class WorkflowQuery
{
    private readonly FactoryDbContext _dbContext;

    public WorkflowQuery(FactoryDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    [GraphQLName("workflowHistory")]
    public async Task<List<WorkflowHistoryDto>> GetWorkflowHistory(
        Guid buildId,
        CancellationToken cancellationToken = default)
    {
        var builds = await _dbContext.Builds
            .Where(b => b.Id == buildId)
            .Include(b => b.WorkflowInstances) // Navigation property
            .FirstOrDefaultAsync(cancellationToken);

        if (builds?.WorkflowInstances == null)
            return new List<WorkflowHistoryDto>();

        return builds.WorkflowInstances
            .Select(w => new WorkflowHistoryDto
            {
                WorkflowInstanceId = w.Id,
                WorkflowName = w.DefinitionId,
                Status = w.Status.ToString(),
                CreatedAt = w.CreatedAt,
                CompletedAt = w.CompletedAt,
                Error = w.Error
            })
            .OrderByDescending(w => w.CreatedAt)
            .ToList();
    }
}
```

