### 5.9 Implement Workflow Cleanup Policy

**File:** `backend/src/FactoryApp.Services/WorkflowCleanupService.cs` (NEW)

Periodic cleanup of completed/failed workflows:

```csharp
public class WorkflowCleanupService : BackgroundService
{
    private readonly FactoryDbContext _dbContext;
    private readonly ILogger<WorkflowCleanupService> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                // Keep only last 30 days of workflow history
                var cutoffDate = DateTime.UtcNow.AddDays(-30);

                var deletedCount = await _dbContext.WorkflowInstances
                    .Where(w => w.CompletedAt < cutoffDate && (w.Status == WorkflowStatus.Finished || w.Status == WorkflowStatus.Failed))
                    .ExecuteDeleteAsync(stoppingToken);

                if (deletedCount > 0)
                    _logger.LogInformation("Cleanup: Deleted {Count} old workflow instances", deletedCount);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Workflow cleanup failed");
            }

            // Run cleanup once per day
            await Task.Delay(TimeSpan.FromHours(24), stoppingToken);
        }
    }
}
```

