**File:** `backend/FactoryApp.Tests/Services/WorkflowRecoveryServiceTests.cs`

```csharp
[Fact]
public async Task ExecuteAsync_FindsRunningWorkflows_ResumesAll()
{
    var service = new WorkflowRecoveryService(serviceProvider, logger, dbContext, workflowHost);

    // Setup: Create running workflow in DB
    var workflow = new WorkflowInstance { Status = WorkflowStatus.Running };
    dbContext.WorkflowInstances.Add(workflow);
    await dbContext.SaveChangesAsync();

    await service.ExecuteAsync(CancellationToken.None);

    var resumed = await dbContext.WorkflowInstances.FindAsync(workflow.Id);
    Assert.NotNull(resumed);
}
```

